config..claude-plugin/plugin.json:
{
  "$schema": "https://json.schemastore.org/claude-code-plugin-manifest.json",
  "name": "activecampaign",
  "displayName": "ActiveCampaign",
  "version": "0.3.1",
  "description": "Marketing automation, CRM, and email marketing powered by ActiveCampaign. Manage contacts, campaigns, automations, deals, and get AI-powered marketing insights — all from Claude.",
  "author": {
    "name": "ActiveCampaign",
    "email": "amurrey@activecampaign.com",
    "url": "https://www.activecampaign.com"
  },
  "homepage": "https://www.activecampaign.com",
  "repository": "https://github.com/ActiveCampaign/activecampaign-plugin",
  "license": "MIT",
  "keywords": ["marketing", "automation", "crm", "email", "campaigns", "deals", "contacts"],
  "userConfig": {
    "server_url": {
      "title": "ActiveCampaign MCP Server URL",
      "type": "string",
      "description": "Your ActiveCampaign MCP Server URL. Find this in your AC account under Settings > Developer > MCP. It looks like: https://yoursubdomain.activehosted.com/api/agents/mcp/http",
      "sensitive": false
    }
  }
}
